import { useMemo, useState } from 'react';
import { Stepper } from '../components/Stepper';
import { Machine } from '../components/Machine';
import { Waveform } from '../components/Waveform';
import { SourceCode } from '../components/SourceCode';
import type { Frame } from '../course/types';
import { adcCode, checkFrame, checksum, contextFrames, displayBudget, dmaFrames, faultFrames, hex, i2cFrames, inversion, iwdgMs, makeFrame, pickTask, pixelAddress, q15Add, q15Mul, qRaw, receiveBurst, uartBits, txCreate, txInterrupt, txPut, wwdgWindow, type Task } from '../models/systems';
const Metric=({name,value}:{name:string;value:string|number})=><div className="metric"><span>{name}</span><strong>{value}</strong></div>;
function Tabs({items,value,set}:{items:string[];value:number;set:(i:number)=>void}){return <div className="experiment-tabs" role="group" aria-label="Choose experiment">{items.map((x,i)=><button key={x} aria-pressed={value===i} onClick={()=>set(i)}>{x}</button>)}</div>;}
function Sequence({frames}:{frames:Frame[]}){return <Stepper frames={frames}>{frame=><Machine active={frame.active}/>}</Stepper>;}
function RTOS(){
 const [tab,setTab]=useState(0),[inherit,setInherit]=useState(false),[work,setWork]=useState(8),[capacity,setCapacity]=useState(3),[queue,setQueue]=useState<number[]>([]),[dropped,setDropped]=useState(0),[msg,setMsg]=useState('Consumer blocked: queue empty'),[stack,setStack]=useState(128),[current,setCurrent]=useState(0);
 const [tasks,setTasks]=useState<Task[]>([{name:'A: display',priority:2,state:'ready'},{name:'B: button',priority:3,state:'sleeping'},{name:'C: calculation',priority:1,state:'ready'},{name:'Idle',priority:0,state:'ready'}]);
 const frames=useMemo(contextFrames,[]);const events=useMemo(()=>inversion(inherit,work),[inherit,work]);
 const invFrames=useMemo<Frame[]>(()=>events.map((e,i)=>({title:e.runner+' · '+e.detail,detail:e.detail,active:'CPU',values:{owner:e.owner,High:e.high,'Low priority':e.lowPriority,event:i}})),[events]);
 return <section className="lab-panel"><h2>Save one task, then run another</h2><p>A task is a function with saved working values and its own stack. The operating system (OS) chooses which task uses the one processor. Open a tab to inspect saving, scheduling, waiting, or message storage. Use Next to advance one event; Replay returns to the beginning.</p><p className="note">Educational event model · values identify contexts, not measured addresses or execution times.</p><Tabs items={['Context switch','Priority inversion','Ready / sleeping','Queue & stack']} value={tab} set={setTab}/>
 {tab===0&&<><p>Leave the first event selected and note A’s R4 value, 41. Press Next to follow saving A and restoring B; B’s R4 is 92. Registers are the processor’s small working storage. PSP, the process stack pointer, selects the task stack. MSP, the main stack pointer, selects the handler stack. A’s values must remain saved while B runs.</p><Stepper frames={frames}>{(f,i)=><><div className="metric-grid">{['A','B'].map(t=><div className="metric" key={t}><strong>Task {t} · separate SRAM stack</strong><p>{t==='A'?(i===0?'Local variables + return path':i<3?'Hardware: r0–r3 r12 LR PC xPSR':'Hardware + software r4–r11'):(i<4?'Previous saved context: R4 = 92':i===4?'r4–r11 restored; hardware frame still saved':'Hardware frame restored; B resumes')}</p><code>R4 = {t==='A'?41:92}</code></div>)}</div><Machine active={f.active}/></>}</Stepper></>}
 {tab===1&&<><p>A mutex permits one owner to use a resource at a time. Low owns it and has 3 work units left before releasing it. High needs that resource and must wait. Leave Priority inheritance off, then turn it on and compare High waiting work units. Medium has {work} units of unrelated ready work. Predict who runs next.</p><div className="controls"><label><input type="checkbox" checked={inherit} onChange={e=>setInherit(e.target.checked)}/> Priority inheritance {inherit?'ON':'OFF'}</label><label>Medium work <input aria-label="Medium work" type="range" min="1" max="16" value={work} onChange={e=>setWork(+e.target.value)}/></label></div><div className="metric-grid"><Metric name="High waiting work units" value={inherit?3:3+work}/><Metric name="Same scenario OFF / ON" value={`${3+work} / 3`}/></div><div className="scheduler-track" aria-label="Running task timeline" style={{display:'flex',flexWrap:'wrap',gap:4,margin:'16px 0'}}>{events.map((e,i)=><span key={i} style={{padding:8,border:'1px solid currentColor',background:e.runner==='High'?'var(--accent-soft)':'transparent'}}>{i}: {e.runner}</span>)}</div><Stepper frames={invFrames}>{(f,i)=><><div role="img" aria-label={`Scheduler event ${i}: ${events[i].runner} runs, High ${events[i].high}, mutex owner ${events[i].owner}`} style={{display:'flex',flexWrap:'wrap',gap:8}}>{['High','Medium','Low'].map(t=><div key={t} className="metric" style={{border:events[i].runner===t?'3px solid var(--accent)':'1px solid currentColor'}}><strong>{t}</strong><p>{events[i].runner===t?'RUNNING':t==='High'?events[i].high:'ready'}</p><p>{events[i].owner===t?'mutex owner':'no mutex'}</p></div>)}</div><div className="metric-grid">{['High','Medium','Low'].map(t=><Metric key={t} name={t} value={t==='High'?String(f.values?.High):t==='Low'?`priority ${f.values?.['Low priority']} · mutex ${f.values?.owner==='Low'?'owner':'free'}`:'priority 2 · unrelated work'}/>)}</div></>}</Stepper><p>Inheritance removes Medium’s interference. It does not remove the three units Low must finish. The timing units here are illustrative, not the course’s measured milliseconds.</p></>}
 {tab===2&&<><p>The scheduler is the code choosing the next task. Set B: button State to ready, then press Schedule next tick; B should run because its priority is 3. Set it back to sleeping and schedule again. Sleeping means waiting for time; blocked means waiting for data or ownership. Only ready tasks compete, and greater task priority wins.</p>{tasks.map((t,i)=><div className="controls" key={t.name}><strong>{i===current&&t.state==='ready'?'▶ LAST DISPATCH ':''}{t.name}</strong><label>Priority <input aria-label={t.name+' priority'} type="number" min="0" max="9" value={t.priority} disabled={i===3} onChange={e=>setTasks(ts=>ts.map((x,k)=>k===i?{...x,priority:Math.min(9,Math.max(0,+e.target.value))}:x))}/></label><label>State <select aria-label={t.name+' state'} value={t.state} disabled={i===3} onChange={e=>setTasks(ts=>ts.map((x,k)=>k===i?{...x,state:e.target.value as Task['state']}:x))}><option value="ready">ready</option><option value="sleeping">sleeping</option><option value="blocked">blocked</option></select></label></div>)}<button onClick={()=>setCurrent(pickTask(tasks,current))}>Schedule next tick</button><p>Equal priorities rotate starting after the current task. If a high-priority task never blocks, low-priority tasks can starve. NVIC exception priority numbers work in the opposite direction.</p></>}
 {tab===3&&<><h3>Store copies until a task can read them</h3><p>Choose Capacity 1. Press ISR produces item twice: the first copy fills the queue and the second increases Dropped ISR items. ISR means interrupt service routine; it cannot wait for the reader. Press Task consumes to free the slot. Then set Allocated stack words to 96 and compare the separate stack demand with its allocation.</p><div className="controls"><label>Capacity <select value={capacity} onChange={e=>{setCapacity(+e.target.value);setQueue([]);setDropped(0);setMsg('New empty queue');}}>{[1,3,5].map(n=><option key={n}>{n}</option>)}</select></label><button onClick={()=>{if(queue.length===capacity){setDropped(d=>d+1);setMsg('ISR cannot block. Item dropped; existing messages preserved.');}else{setQueue(q=>[...q,(dropped+q.length+1)]);setMsg('Message copied in; a blocked consumer becomes ready.');}}}>ISR produces item</button><button onClick={()=>{setQueue(q=>q.slice(1));setMsg(queue.length?'Consumer got first item; one slot is free.':'Consumer blocks until an event arrives.');}}>Task consumes</button><button onClick={()=>{setQueue([]);setDropped(0);setMsg('Consumer blocked: queue empty');}}>Reset queue</button></div><div className="metric-grid"><Metric name="Queue oldest → newest" value={queue.length?queue.join(' → '):'empty'}/><Metric name="Dropped ISR items" value={dropped}/></div><p role="status">{msg}</p><div role="img" aria-label={`Queue ${queue.length} occupied of ${capacity} slots`} style={{display:'flex',flexWrap:'wrap',gap:8}}>{Array.from({length:capacity},(_,slot)=><div className="metric" key={slot}><strong>{slot===0?'oldest / read next':`slot ${slot}`}</strong><p>{queue[slot]??'empty'}</p></div>)}</div><h3>Stack sizing is separate from queue sizing</h3><label>Allocated stack words <input aria-label="Allocated stack words" type="range" min="64" max="512" step="16" value={stack} onChange={e=>setStack(+e.target.value)}/></label><div className="metric-grid"><Metric name="Allocation" value={`${stack} words = ${stack*4} bytes`}/><Metric name="Illustrative deepest path" value="115 words"/><Metric name="Margin" value={`${stack-115} words`}/></div><svg className="diagram" viewBox="0 0 600 90" role="img" aria-label={`Stack demand 115 words, allocation ${stack} words, ${stack<115?'overflow':'within allocation'}`}><text x="20" y="20">SRAM stack · demand 115 words</text><rect x="20" y="35" width={stack} height="25" fill="none" stroke="currentColor"/><rect x="20" y="40" width={115} height="15" fill="var(--accent)"/><path d={`M${20+stack} 30V70`} stroke="currentColor"/><text x={25+stack} y="83">allocation boundary</text></svg><p>{stack<115?'The path overruns its allocation. Valid neighboring SRAM may be overwritten without HardFault.':'Past demand fits. Untested future paths may need more; a high-water mark is evidence, not a guarantee.'}</p></>}
 </section>;
}
function UART(){
 const [tab,setTab]=useState(0),[char,setChar]=useState('A'),[body,setBody]=useState('LED,85'),[damage,setDamage]=useState('none'),[capacity,setCapacity]=useState(64),[burst,setBurst]=useState('hello board'),[line,setLine]=useState(0),[ring,setRing]=useState(()=>txCreate()),[nextByte,setNextByte]=useState(65);
 const byte=char.charCodeAt(0)||0;const frame=makeFrame(body);const received=damage==='corrupt'?frame.slice(0,1)+(frame[1]==='E'?'F':'E')+frame.slice(2):damage==='missing'?frame.slice(0,1)+frame.slice(2):damage==='checksum'?frame.slice(0,-2)+(checksum(body)^1).toString(16).toUpperCase().padStart(2,'0'):frame;
 const result=checkFrame(received), rx=receiveBurst(burst,capacity);const bits=useMemo(()=>uartBits(byte),[byte]);
 const waveFrames=useMemo(()=>bits.map((b,i)=>({title:i===0?'Idle':i===1?'Start':i<10?'Data bit '+(i-2):'Stop / idle',detail:i>=2&&i<10?`Bit ${i-2} is ${b}; receiver builds byte least-significant first.`:`Line ${b?'high':'low'}. ${i===1?'Receiver starts timing.':'Between frames.'}`,active:'UART',values:{line:b,byte:hex(byte),bit:i}})),[bits,byte]);
 const rxFrames=useMemo(()=>[{title:'Wire → RX register',detail:'USART2 reconstructs a byte and sets RXNE.',active:'UART'},{title:'NVIC → CPU handler',detail:'Enabled USART2 IRQ preempts task. The exception path is the same as lesson 05.',active:'NVIC',transfer:{from:'NVIC',to:'CPU',what:'USART2 interrupt request',why:'RXNE is set and its interrupt is enabled.'}},{title:'RDR → RX queue',detail:'ISR reads RDR (clearing RXNE) and copies byte with nonblocking ISR put.',active:'SRAM',transfer:{from:'UART',to:'SRAM',what:'received byte → RX queue',why:'ISR reads RDR and copies into available software storage.'}},{title:'Queue → protocol task',detail:'A successful queue write wakes a waiting task. PendSV runs after handlers; task assembles a line.',active:'CPU',transfer:{from:'SRAM',to:'CPU',what:'queued byte → protocol task',why:'Successful queue write makes the waiting consumer ready.'}},{title:'Frame → Python host',detail:'Validate XOR checksum, parse fields, chart numeric data and track sequence gaps.',active:'UART'}],[]);
 return <section className="lab-panel"><h2>Follow a byte from the wire to a checked message</h2><p>A byte contains eight bits. UART hardware sends them as timed high or low wire levels; the receiver rebuilds the byte. Keep Character set to A and press Next to inspect its start bit and data bits. Other tabs show how storage and message checks can fail after bytes arrive.</p><Tabs items={['Wire waveform','Frame damage','Buffer pressure','RX causal path']} value={tab} set={setTab}/>
 {tab===0&&<><label>Character <input aria-label="Transmit character" value={char} maxLength={1} onChange={e=>setChar(e.target.value.replace(/[^\x20-\x7E]/g,''))}/></label><div className="metric-grid"><Metric name="ASCII byte" value={hex(byte)}/><Metric name="Bit order" value="LSB first"/><Metric name="Nominal byte time" value="86.8 µs at 115200"/></div><Stepper frames={waveFrames}>{(f,i,position)=><><Waveform position={position} bits={bits} labels={['idle','start','d0','d1','d2','d3','d4','d5','d6','d7','stop','idle']}/><p className="note">Inspect signal cell {i}: line is {String(f.values?.line)}. The waveform is slowed, not an oscilloscope capture.</p></>}</Stepper></>}
 {tab===1&&<><p>Leave the body as LED,85 and compare the sender’s frame with the receiver’s. A frame is one marked message; its checksum is a calculated check value. Choose Corrupted body byte under Inject and watch the receiver reject it. The XOR row combines each character’s eight-bit code in order; XOR sets a bit where its two inputs differ.</p><label>Printable ASCII body <input aria-label="Frame body" maxLength={60} value={body} onChange={e=>{const next=e.target.value.replace(/[^\x20-\x7E]/g,'').replace(/[$*]/g,'');setBody(next);if(!next)setDamage('none');}}/></label><div className="controls"><label>Inject <select aria-label="Frame damage" value={damage} onChange={e=>setDamage(e.target.value)}><option value="none">No damage</option><option value="corrupt" disabled={!body}>Corrupted body byte</option><option value="missing" disabled={!body}>Missing body byte</option><option value="checksum">Wrong checksum</option></select></label></div><div className="metric-grid"><Metric name="Sender frame" value={frame}/><Metric name="On receiver" value={received}/><Metric name="Computed body XOR" value={hex(checksum(body))}/></div><h3>Board / host decision</h3><p role="status">{result.ok?`Accepted: ${result.body}. A valid LED command can change output; host can log an ACK.`:`Rejected: ${result.reason}. Board does not apply damaged command; host counts a bad frame.`}</p><div style={{display:'flex',flexWrap:'wrap',gap:6}} aria-label="XOR checksum accumulation">{Array.from(body).map((c,i)=><span className="note" key={i}>{c}: {hex(c.charCodeAt(0))} → {hex(checksum(body.slice(0,i+1)))}</span>)}</div><SourceCode label="Actual course expression · proto.c" code={'cs ^= (uint8_t)body[i];'}/><p>Line endings delimit messages. A checksummed body excludes $, *, hex digits and CR/LF. Two changes in the same bit position can cancel and pass XOR.</p><pre className="code"><code>{`python host.py --frame "${body}"\n${frame}\npython host.py --file capture.txt`}</code></pre></>}
 {tab===2&&<><p>Reduce RX queue capacity below the length of Incoming burst. Watch Stored queue stop at that limit while Software drops rises. RX means receive, TX means transmit. This burst arrives before the task removes any bytes; ordinary wire delivery spaces bytes over time. Below, press Task queues A and then TXE interrupt to move the queued byte to the wire. TXE means the transmit register is empty; TXEIE is its interrupt-enable bit.</p><label>Incoming burst <input aria-label="Incoming burst" maxLength={100} value={burst} onChange={e=>setBurst(e.target.value.replace(/[^\x20-\x7E]/g,''))}/></label><label>RX queue capacity <input aria-label="RX queue capacity" type="range" min="1" max="64" value={capacity} onChange={e=>setCapacity(+e.target.value)}/></label><div className="metric-grid"><Metric name="ISR received" value={burst.length}/><Metric name="Stored queue" value={`${rx.queue.length} / ${capacity}`}/><Metric name="Software drops" value={rx.dropped}/><Metric name="Hardware overruns" value="0 in this model"/></div><p><code>{rx.queue.join('')}</code> remains. {rx.dropped?'ISR completed but storage filled. A truncated framed command should fail validation.':'All bytes fit, but task must drain before further bursts.'}</p><h3>TX ring: tasks produce, ISR consumes</h3><p>Eight slots here expose wrapping; real course ring has 256 slots. One stays reserved so head=tail means empty.</p><div className="controls"><button onClick={()=>{setRing(r=>txPut(r,nextByte));setNextByte(n=>n===90?65:n+1);}}>Task queues {String.fromCharCode(nextByte)}</button><button onClick={()=>setRing(txInterrupt)}>TXE interrupt</button><button onClick={()=>{setRing(txCreate());setNextByte(65);}}>Reset TX ring</button></div><div className="metric-grid"><Metric name="Head / tail" value={`${ring.head} / ${ring.tail}`}/><Metric name="TXEIE" value={ring.irq?'enabled':'disabled'}/><Metric name="Bytes on wire" value={ring.sent.map(b=>String.fromCharCode(b)).join('')||'none'}/></div><div style={{display:'flex',gap:4,flexWrap:'wrap'}}>{ring.data.map((b,i)=><span className="note" key={i}>{i}: {b===null?'·':String.fromCharCode(b)} {i===ring.head?'H':''}{i===ring.tail?'T':''}</span>)}</div><p>Producer publishes byte before advancing head. ISR consumes before advancing tail. After last byte, one more TXE interrupt sees empty and disables TXEIE. A full ring needs producer waiting; this button attempt leaves contents unchanged.</p><SourceCode activeLine={line} onSelect={setLine} label="Actual course excerpts · uart.c" code={'USART2->TDR = tx_ring[tx_tail];\ntx_tail = (uint16_t)((tx_tail + 1u) % TX_SIZE);\nUSART2->CR1 &= ~USART_CR1_TXEIE_TXFNFIE;'}/><p>{line===2?'When the ring is empty, disable TXEIE. Otherwise empty hardware keeps requesting an interrupt.':line===1?'Advance consumer-owned tail, wrapping at 256. Producer owns head; line-level mutex serializes tasks.':'Write one queued byte to transmit register. Hardware shifts it while CPU returns to other work.'}</p></>}
 {tab===3&&<><p>Press Next to trace a received byte from the wire into hardware, then into a software queue. RXNE means a byte is ready; RDR is the receive data register. NVIC is the interrupt controller. The ISR, interrupt service routine, copies promptly; a task later assembles and checks the message. The host is the computer reading board output.</p><Sequence frames={rxFrames}/></>}
 </section>;
}
function Sensors(){
 const [tab,setTab]=useState(0),[volts,setVolts]=useState(1.65),[ref,setRef]=useState(3.3),[ack,setAck]=useState(true),[reg,setReg]=useState(10),[val,setVal]=useState(4),[selected,setSelected]=useState(0);
 const code=adcCode(volts,ref);const i2c=useMemo(()=>i2cFrames(ack),[ack]);const word=(reg<<8)|val;
 const spi=useMemo<Frame[]>(()=>[{title:'Select target',detail:'PB0 CS goes low. MAX7219 begins receiving a 16-bit command.',values:{CS:0,latched:'previous value'}},...Array.from({length:16},(_,i)=>({title:'Shift bit '+(15-i),detail:`SCK rising edge samples MOSI=${(word>>(15-i))&1}. Bits shift MSB first.`,values:{CS:0,MOSI:(word>>(15-i))&1,shifted:hex(word>>Math.max(0,15-i),4)}})),{title:'Latch command',detail:`CS rises. MAX7219 register ${hex(reg)} accepts data ${hex(val)}. It sends no acknowledgement on this connection.`,values:{CS:1,register:hex(reg),data:hex(val)}}], [word,reg,val]);
 const init=useMemo(()=>[{title:'Clock and regulator',detail:'Enable ADC clock and regulator; wait required settling interval.',active:'ADC',values:{clock:'on',regulator:'settling',ADCAL:0,ADEN:0,ADRDY:0,EOC:0,DR:'old reading'}},{title:'Calibrate while disabled',detail:'Start ADCAL and wait with a bound for it to clear.',active:'ADC',values:{regulator:'settled',ADCAL:'1 → 0 after calibration',ADEN:0,ADRDY:0,EOC:0,DR:'old reading'}},{title:'Enable and ready',detail:'ADEN turns converter on. ADRDY confirms it is ready.',active:'ADC',values:{ADCAL:0,ADEN:1,ADRDY:1,EOC:0,DR:'old reading'}},{title:'Select channel',detail:'PA4 analog input; CHSELR update and CCRDY synchronization precede conversion.',active:'ADC',values:{ADEN:1,ADRDY:1,CHSELR:'PA4',CCRDY:1,EOC:0,DR:'old reading'}},{title:'Start conversion',detail:`ADSTART captures PA4 = ${volts.toFixed(2)} V relative to VDDA = ${ref.toFixed(2)} V. Conversion is in progress; old DR is not the new sample.`,active:'ADC',values:{ADSTART:1,EOC:0,DR:'old reading'}},{title:'End of conversion',detail:'EOC permits reading DR. A numeric result is ready.',active:'ADC',transfer:{from:'ADC',to:'CPU',what:`DR = ${code}`,why:'EOC confirms the conversion result can be read.'},values:{ADSTART:0,EOC:1,DR:code}}],[code,volts,ref]);
 return <section className="lab-panel"><h2>Convert voltage or exchange digital data</h2><p>An ADC, analog-to-digital converter, turns voltage into a number. I²C and SPI are buses: connections that transfer already-digital data between chips. Start with ADC voltage; other tabs show initialization and a complete chip transaction.</p><Tabs items={['ADC voltage','ADC readiness','I²C register read','SPI command']} value={tab} set={setTab}/>
 {tab===0&&<><p>Leave PA4 input at 1.65 V and note the result in DR, the data register. Reduce Reference VDDA from 3.30 V to 3.00 V. VDDA is the ADC supply and reference voltage here. The same input now occupies a larger fraction of that reference, so the reading rises. Each bin is a voltage interval that maps to one code.</p><label>PA4 input {volts.toFixed(2)} V <input aria-label="ADC voltage" type="range" min="0" max="3.3" step="0.01" value={volts} onChange={e=>setVolts(+e.target.value)}/></label><label>Reference VDDA {ref.toFixed(2)} V <input aria-label="ADC reference" type="range" min="2.7" max="3.6" step="0.01" value={ref} onChange={e=>setRef(+e.target.value)}/></label><div className="metric-grid"><Metric name="12-bit DR" value={`${code} · ${hex(code,3)}`}/><Metric name="Ideal bin width" value={`${(ref/4096*1000).toFixed(3)} mV`}/><Metric name="MAX7219 intensity" value={code>>8}/></div><svg className="diagram" viewBox="0 0 600 150" role="img" aria-label={`ADC input ${volts} volts produces code ${code}`}><rect x="20" y="25" width="170" height="75" rx="8" fill="none" stroke="currentColor"/><text x="105" y="55" textAnchor="middle">PA4 potentiometer</text><text x="105" y="80" textAnchor="middle">{volts.toFixed(2)} V</text><path d="M195 60 H230 M225 55 L230 60 L225 65" stroke="currentColor" fill="none"/><rect x="240" y="25" width="140" height="75" rx="8" fill="none" stroke="currentColor"/><text x="310" y="55" textAnchor="middle">ADC bins</text><text x="310" y="80" textAnchor="middle">0 … 4095</text><path d="M385 60 H420" stroke="currentColor"/><text x="500" y="65" textAnchor="middle">DR = {code}</text><rect x="240" y="106" width="140" height="8" fill="none" stroke="currentColor"/><rect x="240" y="106" width={140*code/4095} height="8" fill="var(--accent)"/><text x="310" y="129" textAnchor="middle">{(Math.min(1,volts/ref)*100).toFixed(1)}% of VDDA</text></svg><p>{volts>ref?'Input exceeds reference: model saturates at 4095. Real pin limits must also be respected.':'Reference defines full scale; code is dimensionless until software assigns units.'} Sensor noise, offsets and settling are omitted.</p><SourceCode code={'int32_t pot = adc_read(ADC_CH_PA4);\nmax_cmd(MAX_INTENSITY, (uint8_t)(pot >> 8));'} label="Actual course excerpts · Main.c" activeLine={selected} onSelect={setSelected}/><p>{selected===0?'ADC samples PA4 and returns a number.':'Discard low eight bits to select display intensity 0–15; then send SPI command.'}</p></>}
 {tab===1&&<><p>Press Next through preparation before conversion. Calibration measures internal converter error before use. ADCAL starts it; ADEN enables the ADC; ADRDY says it is ready. CHSELR selects the input channel, CCRDY confirms selection, ADSTART begins conversion, and EOC means end of conversion. Only then is a new DR reading available.</p><Sequence frames={init}/></>}
 {tab===2&&<><p>The MPU6050 is the motion sensor. WHO_AM_I is its identity register. Press Next to follow a read: device address 0x68 chooses the chip; register address 0x75 chooses its identity value. ACK means acknowledge, accepted at this transfer stage. Uncheck Sensor connected and step again to see the failed address stop the transaction.</p><label><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)}/> Sensor connected (address ACK)</label><Stepper frames={i2c}>{(f,i,position)=><><div className="metric-grid"><Metric name="Controller" value="I2C1 · PB8 SCL / PB9 SDA"/><Metric name="Device" value={ack?'MPU6050 @ 0x68':'no responder'}/><Metric name="Transaction event" value={i+1}/></div><div className="diagram-scroll" tabIndex={0} role="region" aria-label="I²C controller and device signals; scroll horizontally on narrow screens"><svg className="diagram" viewBox="0 0 600 180" role="img" aria-label={`I2C ${f.title}: ${String(f.values?.byte||f.values?.RXDR||'bus condition')}`}><rect x="15" y="15" width="180" height="60" fill="none" stroke="currentColor"/><text x="105" y="40" textAnchor="middle">Controller · I2C1</text><text x="105" y="61" textAnchor="middle">{i===7?'RXDR ← 0x68':i===8?'NACK · last byte':'send request'}</text><rect x="405" y="15" width="180" height="60" fill="none" stroke="currentColor"/><text x="495" y="40" textAnchor="middle">{ack?'MPU6050 · 0x68':'No responder'}</text><text x="495" y="61" textAnchor="middle">{ack?'ID 0x68 @ 0x75':'SDA remains released'}</text><path d="M195 43H405" stroke="currentColor"/>{(f.values?.byte||f.values?.RXDR)&&<g className="moving-object" transform={`translate(${i===7?405-(position-i)*210:195+(position-i)*210} 43)`}><circle r="5" fill="var(--accent)"/><text y="17" textAnchor="middle">{String(f.values?.byte||f.values?.RXDR)}</text></g>}<text x="300" y="35" textAnchor="middle">{i===7?'0x68 ← device':'controller → request'}</text><text x="15" y="106">SCL clock</text><text x="15" y="151">SDA data</text>{(()=>{const byte=f.values?.byte||f.values?.RXDR;const hasByte=byte!==undefined;const isAck=f.title.includes('ACK');const count=hasByte?8:isAck?1:2;const width=450/count;const start=f.title.includes('START'),stop=f.title==='STOP';return Array.from({length:count},(_,bit)=>{const data=hasByte?((Number(byte)>>(7-bit))&1):isAck?(f.title.includes('NACK')?1:0):start?(bit===0?1:0):stop?(bit===0?0:1):1;const x=120+bit*width;return <g key={bit}><path d={hasByte||isAck?`M${x} 110v-20h${width/2}v20h${width/2}`:`M${x} 90h${width}`} fill="none" stroke="currentColor"/><path d={`M${x} ${data?135:155}h${width}${bit+1<count?'v'+((hasByte?((Number(byte)>>(6-bit))&1):start?0:stop?1:1)-data)*-20:''}`} fill="none" stroke="currentColor"/><text x={x+width/2} y="177" textAnchor="middle">{isAck?'clock 9':hasByte?`b${7-bit}=${data}`:bit===0?'before':'after'}</text></g>})})()}</svg></div><p>{f.title==='START'||f.title==='Repeated START'?'START: SDA falls while SCL is high; controller begins or redirects the transaction.':f.title==='STOP'?'STOP: SDA rises while SCL is high; the controller releases the bus.':`Current transfer: ${f.title}. Clock nine is acknowledgement, not a ninth data bit.`}</p></>}</Stepper><p>SCL is the clock wire; SDA is data. Open-drain outputs can pull a wire low but release it for an external pull-up resistor to bring it high. An ACK is SDA low on clock nine. A final controller NACK means finished; an address NACK means no receiver accepted the request.</p></>}
 {tab===3&&<><p>Leave register 0x0A intensity selected and data at 4. The upper byte chooses a setting; the lower byte gives its value. Press Next through all sixteen data bits and the final latch event. CS is chip select, SCK is clock, and MOSI carries controller-to-display data. The setting changes when CS rises after the complete command.</p><div className="controls"><label>MAX7219 register <select value={reg} onChange={e=>setReg(+e.target.value)}><option value="10">0x0A intensity</option><option value="1">0x01 row 0</option><option value="12">0x0C shutdown</option></select></label><label>Data byte <input aria-label="SPI data byte" type="range" min="0" max="255" value={val} onChange={e=>setVal(+e.target.value)}/></label></div><div className="metric-grid"><Metric name="16-bit word" value={hex(word,4)}/><Metric name="Meaning" value={reg===10?`Intensity uses low 4 bits: ${val&15}`:reg===12?((val&1)?'Display awake':'Display shutdown'):`Row LEDs ${val.toString(2).padStart(8,'0')}`}/></div><Stepper frames={spi}>{(f,i,position)=><><Waveform position={i===0?undefined:Math.min(16,Math.max(0,position-1))} bits={Array.from({length:16},(_,i)=>(word>>(15-i))&1)} labels={Array.from({length:16},(_,i)=>'b'+(15-i))}/><div className="metric-grid"><Metric name="CS · chip select" value={i===17?'1 · latch completed':'0 · receiving'}/><Metric name="Bits sampled" value={Math.min(16,i)}/><Metric name="Shift register" value={i===0?'empty':hex(word>>Math.max(0,16-Math.min(i,16)),4)}/><Metric name="Latched display setting" value={i===17?`${hex(reg)} ← ${hex(val)}`:'previous setting · unchanged'}/></div><p>{f.detail}</p></>}</Stepper><p>Mode 0: data sampled on rising clock edges, changed for the next bit on falling edges. This course wiring only sends MOSI; no returned byte proves the display is alive.</p></>}
 </section>;
}
function FixedDMA(){
 const [tab,setTab]=useState(0),[a,setA]=useState(0.8),[b,setB]=useState(0.8),[sat,setSat]=useState(true),[dma,setDma]=useState(true),[support,setSupport]=useState(true);
 const ar=qRaw(a),br=qRaw(b),product=q15Mul(ar,br),sum=q15Add(ar,br,sat);const frames=useMemo(()=>dmaFrames(dma&&support,dma),[dma,support]);
 return <section className="lab-panel"><h2>Store fractions and move samples without per-sample CPU copies</h2><p>Fixed point stores an integer with an agreed scale. Set Value A to 0.5 and compare Stored with Decoded: Q15 stores 16384, then divides by 32768 to recover 0.5. Error is decoded value minus requested value. Other tabs test arithmetic limits and DMA, direct memory access hardware that copies samples.</p><Tabs items={['Number representations','Arithmetic hazards','DMA and CPU']} value={tab} set={setTab}/>
 {tab!==2&&<><label>Value A = {a.toFixed(4)} <input aria-label="Fixed value A" type="range" min="-1" max="1" step="0.0001" value={a} onChange={e=>setA(+e.target.value)}/></label>{tab===0?<><div className="metric-grid">{[{name:'int32',raw:Math.trunc(a),scale:1},{name:'Q15',raw:ar,scale:32768},{name:'Q16.16',raw:qRaw(a,16),scale:65536},{name:'float32',raw:Math.fround(a),scale:1}].map(n=><div className="metric" key={n.name}><strong>{n.name}</strong><p>Stored {n.raw}</p><p>Decoded {(n.raw/n.scale).toFixed(7)}</p><p>Error {(n.raw/n.scale-a).toExponential(2)}</p></div>)}</div><p>Raw Q15 {ar} = <code>{(ar&65535).toString(2).padStart(16,'0')}</code>. Decode by dividing by 32768. +1 clamps to 32767 here; −1 fits exactly. Conversion here is safe and saturating, unlike passing out-of-range constants to the course Q15 macro.</p></>:<><p>Press Try addition overflow: A and B become 0.8 and wrapping addition produces a negative result. Enable Saturating addition to clamp to the greatest Q15 value instead. Then press Try −1 × −1 and compare the ideal positive answer with Q15’s limit.</p><label>Value B = {b.toFixed(4)} <input aria-label="Fixed value B" type="range" min="-1" max="1" step="0.0001" value={b} onChange={e=>setB(+e.target.value)}/></label><label><input type="checkbox" checked={sat} onChange={e=>setSat(e.target.checked)}/> Saturating addition</label><div className="metric-grid"><Metric name="A + B ideal" value={(a+b).toFixed(6)}/><Metric name="A + B Q15" value={`${sum} / 32768 = ${(sum/32768).toFixed(6)}`}/><Metric name="Wide A × B raw" value={ar*br}/><Metric name="Rounded product Q15" value={`${product} / 32768 = ${(product/32768).toFixed(6)}`}/></div><p>{!sat&&(ar+br>32767||ar+br< -32768)?'This integer sum exceeds signed 16-bit range: wrapping changes its interpreted sign. Bits fit but the physical meaning is broken.':sat?'Saturating arithmetic clamps only when the integer result exceeds −32768 … 32767. Correct arithmetic still requires a range/precision budget.':'This sum fits signed 16-bit range, so wrapping and saturating additions agree.'}</p><SourceCode code={'int32_t p = (int32_t)a * b;\np += 1 << 14;\nreturn q15_sat32(p >> 15);'} label="Actual course excerpt · fix.h"/><p>The wide temporary product has thirty fractional bits because both inputs had fifteen. A least significant bit (LSB) is one stored result step. Adding 16384 adds half a final-result step before shifting right fifteen bits. This rounding expression sends exact halfway cases toward positive infinity.</p><button onClick={()=>{setA(-1);setB(-1);}}>Try −1 × −1</button><button onClick={()=>{setA(0.8);setB(0.8);setSat(false);}}>Try addition overflow</button></>}</>}
 {tab===2&&<><p>Press Next and compare CPU lane with Buffer. With DMA requested and supported, hardware copies each ADC sample while the CPU calculates. Turn DMA transfer requested off to see the CPU perform copies instead. Uncheck Teaching hardware supports DMA to see the timeout and fallback path; a sentinel is a recognizable initial value used to detect whether a write occurred.</p><div className="controls"><label><input type="checkbox" checked={dma} onChange={e=>setDma(e.target.checked)}/> DMA transfer requested</label><label><input type="checkbox" checked={support} onChange={e=>setSupport(e.target.checked)}/> Teaching hardware supports DMA</label></div>{dma&&!support&&<p role="status" className="note">Sentinel 0xFFFF stays unchanged → bounded wait times out → disable DMA → use CPU polling. Pinned course documents Wokwi DMA as unavailable.</p>}<Stepper frames={frames}>{(f,i)=><><div className="metric-grid"><Metric name="CPU lane" value={String(f.values?.CPU)}/><Metric name="Mover lane" value={f.title}/><Metric name="Buffer" value={String(f.values?.RAM||'prior contents')}/></div><Machine active={f.active}/></>}</Stepper><p>CPU continues independent calculation with DMA, but both masters share bus resources. A completed circular buffer can be updated while the CPU reads; synchronization and overrun handling remain necessary.</p><SourceCode code={'DMA1_Channel1->CPAR  = (uint32_t)&ADC1->DR;\nDMA1_Channel1->CMAR  = (uint32_t)scan_buf;\nDMA1_Channel1->CNDTR = SCAN_CH;'} label="Actual course excerpts · dma.c"/></>}
 </section>;
}
function Faults(){
 const [tab,setTab]=useState(0),[kind,setKind]=useState('unaligned'),[dog,setDog]=useState('iwdg'),[policy,setPolicy]=useState('heartbeat'),[failure,setFailure]=useState('job'),[elapsed,setElapsed]=useState(0),[pr,setPr]=useState(3),[reload,setReload]=useState(999),[sleep,setSleep]=useState(true),[busy,setBusy]=useState(20),[window,setWindow]=useState(96),[counter,setCounter]=useState(127),[windowMessage,setWindowMessage]=useState('Counter starts at 0x7F');
 const frames=useMemo(()=>faultFrames(kind),[kind]);const timeout=iwdgMs(pr,reload);const blockedClock=dog==='soft'&&failure==='masked';const feeds=policy==='isr'&&failure!=='masked'||policy==='loop'&&failure==='job';const left=blockedClock||feeds?timeout:Math.max(0,timeout-elapsed);const expired=left===0;
 return <section className="lab-panel"><h2>Detect a fault, lost progress, or unsafe watchdog feeding</h2><p>A fault prevents normal processor execution; a hang stops useful progress, and memory corruption can occur without either. Select Failure and press Next to inspect available evidence. Other tabs compare watchdog timers, which reset after a missed refresh, and waiting during idle time.</p><Tabs items={['Crash evidence','Watchdog honesty','Sleep and useful load','WWDG window']} value={tab} set={setTab}/>
 {tab===0&&<><label>Failure <select aria-label="Crash scenario" value={kind} onChange={e=>setKind(e.target.value)}><option value="unaligned">Unaligned word load</option><option value="pointer">Unmapped pointer access</option><option value="udf">Undefined instruction</option><option value="overflow">Stack overruns into valid SRAM</option><option value="hang">Main keeps looping but makes no progress</option></select></label><Sequence frames={frames}/><div className="metric-grid"><Metric name="Fault status on M0+" value="No CFSR / BFAR"/><Metric name="Evidence" value={kind==='hang'?'Missing heartbeat':kind==='overflow'?'Corrupted neighbor or stack marker':'Saved PC, registers, instruction'}/><Metric name="Frame location" value={kind==='hang'||kind==='overflow'?'No guaranteed exception frame':'MSP or PSP; EXC_RETURN bit 2'}/></div><p>PC, the program counter, identifies an instruction address. MSP and PSP are the main and process stack pointers; the exception-return value selects the interrupted stack. CFSR and BFAR are fault-detail registers found on larger cores, not this M0+. The classifier’s verdict is a diagnosis from clues, not a guaranteed hardware cause code. A stack overwrite inside SRAM may continue silently. .noinit retention across software reset must be validated; power loss can destroy it.</p></>}
 {tab===1&&<><p>Leave Independent IWDG, All job heartbeats, and One job stops completing selected. A heartbeat is a record that a job finished; feeding refreshes the watchdog counter. Press Advance ¼ timeout until it expires. Then select Every SysTick ISR and repeat: an interrupt service routine keeps feeding even though the required job is missing. PR selects the clock divider and RLR sets the reload count.</p><div className="controls"><label>Dog <select aria-label="Dog" value={dog} onChange={e=>{setDog(e.target.value);setElapsed(0);}}><option value="iwdg">Independent IWDG</option><option value="soft">SysTick software dog</option></select></label><label>Feed policy <select aria-label="Feed policy" value={policy} onChange={e=>{setPolicy(e.target.value);setElapsed(0);}}><option value="heartbeat">All job heartbeats</option><option value="isr">Every SysTick ISR</option><option value="loop">Every main loop</option></select></label><label>Failure <select aria-label="Failure" value={failure} onChange={e=>{setFailure(e.target.value);setElapsed(0);}}><option value="job">One job stops completing</option><option value="hang">Main loop hangs, IRQs run</option><option value="masked">Hang with IRQs masked</option></select></label></div><div className="controls"><label>PR <input type="number" min="0" max="6" value={pr} onChange={e=>{setPr(Math.min(6,Math.max(0,+e.target.value)));setElapsed(0);}}/></label><label>Reload RLR <input type="number" min="0" max="4095" value={reload} onChange={e=>{setReload(Math.min(4095,Math.max(0,+e.target.value)));setElapsed(0);}}/></label></div><div className="metric-grid"><Metric name="Nominal configured timeout" value={`${timeout.toFixed(2)} ms`}/><Metric name="Elapsed teaching time" value={`${elapsed} ms`}/><Metric name="Counter remaining" value={`${left.toFixed(2)} ms`}/><Metric name="Missing heartbeats" value="job 2: bit 0b010"/></div><progress aria-label="Watchdog remaining" max={timeout} value={left}/><div className="controls"><button onClick={()=>setElapsed(t=>t+Math.max(1,Math.ceil(timeout/4)))}>Advance ¼ timeout</button><button onClick={()=>setElapsed(0)}>Reset experiment</button></div><p role="status">{expired?'Expired → reset. Startup reruns; retained flight recorder can report missing job.':blockedClock?'Counter frozen: SysTick cannot run with IRQs masked. Software dog cannot recover this failure.':feeds?'Counter repeatedly refreshed despite missing useful work. Feeding policy hides failure.':'No complete heartbeat round: independent watchdog keeps counting toward recovery.'}</p><p>IWDG means independent watchdog; LSI is its low-speed internal oscillator. The formula uses nominal LSI=32 kHz; actual oscillator tolerance changes timeout. Soft dog slider uses the same illustrative timeout for comparison. Wokwi does not implement IWDG; this is a hardware teaching model. WWDG additionally has an early-feed window and peripheral-clock dependence.</p><SourceCode label="Actual course excerpt · wdog.h" code={'if ((h->seen & h->expected) != h->expected) { return 0; }\nh->seen = 0;\nreturn 1;'}/></>}
 {tab===2&&<><p>Leave useful work at 20 ms per 100 ms and toggle WFI during idle. WFI means Wait For Interrupt. Watch useful CPU load stay at 20% while Core while idle changes from a polling loop to waiting. The 80 ms without useful work need not execute repeated checks.</p><label>Useful work per 100 ms: {busy} ms <input aria-label="Useful work" type="range" min="0" max="100" value={busy} onChange={e=>setBusy(+e.target.value)}/></label><label><input type="checkbox" checked={sleep} onChange={e=>setSleep(e.target.checked)}/> WFI during idle</label><div className="metric-grid"><Metric name="Useful CPU load" value={`${busy}%`}/><Metric name="Idle time" value={`${100-busy} ms / 100 ms`}/><Metric name="Core while idle" value={sleep?'Waiting for interrupt':'Executing polling loop'}/></div><div aria-label="Work and idle timeline" style={{display:'flex',height:48,border:'1px solid currentColor',margin:'20px 0'}}><span style={{width:busy+'%',background:'var(--accent-soft)',overflow:'hidden'}}>Work</span><span style={{width:(100-busy)+'%',overflow:'hidden'}}>{sleep?'WFI sleep':'Spin'}</span></div><p>Useful work and its load percentage are unchanged. On real hardware, sleeping stops unnecessary core switching. No current, battery life or power measurement is inferred from this browser model. Peripherals and wake conditions still require configured clocks.</p></>}
 {tab===3&&<><p>WWDG means window watchdog. With threshold 0x60 and counter 0x7F, press Feed WWDG to see an early-refresh rejection. Reset experiment, then press Advance eight counter ticks four times to reach 0x5F and feed again. Refresh is accepted only inside the stated window; counting below 0x40 expires. This detects refreshes occurring too early as well as too late.</p><label>Window threshold {hex(window)} <input aria-label="WWDG window" type="range" min="64" max="127" value={window} onChange={e=>setWindow(+e.target.value)}/></label><div className="metric-grid"><Metric name="7-bit counter" value={hex(counter)}/><Metric name="Feed rule" value={`0x40 ≤ T ≤ ${hex(window)}`}/></div><svg className="diagram" viewBox="0 0 600 100" role="img" aria-label={`Window ${hex(window)}; counter ${hex(counter)}; ${wwdgWindow(counter,window,true)}`}><rect x="20" y="30" width="560" height="20" fill="none" stroke="currentColor"/><rect x="20" y="30" width={560*(window-63)/64} height="20" fill="var(--accent-soft)"/><path d={`M${20+560*(Math.max(63,counter)-63)/64} 20v40`} stroke="currentColor" strokeWidth="3"/><text x="20" y="80">0x40 · late boundary</text><text x="580" y="80" textAnchor="end">0x7F · reloaded</text><text x="300" y="20" textAnchor="middle">{counter<64?'EXPIRED':counter>window?'too early to feed':'valid feed window'}</text></svg><progress aria-label="Window watchdog counter" max="127" value={counter}/><div className="controls"><button disabled={counter<64||windowMessage.includes('reset')} onClick={()=>{const n=counter-8;setCounter(n);setWindowMessage(wwdgWindow(n,window,false));}}>Advance eight counter ticks</button><button disabled={counter<64||windowMessage.includes('reset')} onClick={()=>{const outcome=wwdgWindow(counter,window,true);setWindowMessage(outcome);if(outcome==='valid refresh')setCounter(127);}}>Feed WWDG</button><button onClick={()=>{setCounter(127);setWindowMessage('Reset experiment: counter reloaded 0x7F');}}>Reset experiment</button></div><p role="status">{windowMessage}. A reset is shown as an outcome, not actually resetting the browser. Counter crossing 0x40 → 0x3F expires; feeding while above window is early. Course default W=0x7F disables early-feed rejection; Lab asks W=0x60.</p><p>WWDG depends on PCLK. Wokwi lists it implemented but not yet tested; this deterministic model represents the documented window rule.</p></>}
 </section>;
}
function Game(){
 const [tab,setTab]=useState(0),[x,setX]=useState(20),[y,setY]=useState(20),[full,setFull]=useState(false),[clock,setClock]=useState(400000),[dirty,setDirty]=useState<number[]>([]),[pixel,setPixel]=useState({x:20,y:20}),[screen,setScreen]=useState({x:20,y:20}),[message,setMessage]=useState('RAM and OLED agree. Choose a new target, then step the pipeline.'),[mode,setMode]=useState('menu');
 const addr=pixelAddress(x,y);const budget=displayBudget(full?8:dirty.length,clock);
 const frames=useMemo<Frame[]>(()=>[{title:'Input sampled',detail:`Joystick/button teaching input selects target (${x}, ${y}). Debounced press is an edge; held state is separate.`,values:{input:`target ${x},${y}`,RAM:'previous',OLED:'previous'}},{title:'Game updates',detail:'A fixed 20 ms logic tick updates the model. No bus transfer yet.',values:{logic:`new position ${x},${y}`,RAM:'previous',OLED:'previous'}},{title:'Framebuffer changes',detail:`Erase old pixel, set new pixel. Byte ${addr.index}, bit ${addr.bit}, mask ${hex(addr.mask)}. Mark old and new pages dirty.`,active:'SRAM',values:{page:addr.page,column:x,bit:addr.bit,OLED:'previous'}},{title:'Flush selected pages',detail:'I²C window commands (0x00) precede page pixel data (0x40). A failure would retain dirty bits for retry.',active:'GPIO',values:{address:'0x3C',page:addr.page,byteMask:hex(addr.mask)}},{title:'Display RAM changes',detail:'SSD1306 controller now has new pixels. It refreshes glass independently of the CPU.',values:{OLED:`new position ${x},${y}`,RAM:'matches OLED'}}],[x,y,addr.index,addr.bit,addr.mask,addr.page]);
 const move=()=>{const pages=[...new Set([...dirty,pixel.y>>3,y>>3])];setDirty(pages);setPixel({x,y});setMessage(`RAM changed to (${x},${y}); OLED still (${screen.x},${screen.y}). Dirty pages: ${pages.join(', ')}.`);};
 return <section className="lab-panel"><h2>Follow input through RAM and display memory</h2><p>A framebuffer is CPU RAM containing intended pixels. The OLED, organic light-emitting diode display, has separate controller RAM. Move Target Y to 30 and press Next. Watch the left framebuffer point move before the right display point; the transfer between them is called a flush.</p><Tabs items={['Frame pipeline','Pixel & bus budget','Arcade state machine']} value={tab} set={setTab}/>
 {tab===0&&<><label>Target X <input aria-label="Target X" type="range" min="0" max="127" value={x} onChange={e=>setX(+e.target.value)}/></label><label>Target Y <input aria-label="Target Y" type="range" min="0" max="63" value={y} onChange={e=>setY(+e.target.value)}/></label><Stepper frames={frames}>{(_,i,position)=><div className="diagram-scroll" tabIndex={0} role="region" aria-label="Framebuffer and OLED diagram, scroll horizontally on narrow screens"><svg className="diagram" viewBox="0 0 600 210" role="img" aria-label={`Framebuffer ${i>=2?'updated':'previous'}; OLED ${i>=4?'updated':'previous'}`}><text x="145" y="25" textAnchor="middle">SRAM framebuffer</text><text x="445" y="25" textAnchor="middle">OLED display RAM</text>{[0,1].map(n=><g key={n}><rect x={20+n*300} y="45" width="256" height="128" fill="none" stroke="currentColor"/>{Array.from({length:8},(_,p)=><line key={p} x1={20+n*300} x2={276+n*300} y1={45+p*16} y2={45+p*16} stroke="currentColor" opacity="0.15"/>)}<circle cx={20+n*300+2*((n===0?i>=2:i>=4)?x:20)} cy={45+2*((n===0?i>=2:i>=4)?y:20)} r="4" fill="currentColor"/></g>)}{i===2&&<g><circle cx={20+x*2} cy={45+y*2} r={7+3*(position-i)} fill="none" stroke="currentColor"/><text x="145" y="198" textAnchor="middle">write byte {addr.index} · mask {hex(addr.mask)}</text></g>}<path className="diagram-wire" d="M276 109H320"/>{i===3&&<g className="moving-object" transform={`translate(${276+(position-i)*44} 109)`}><circle r="5" fill="var(--accent)"/><text y="-12" textAnchor="middle">{hex(addr.mask)}</text></g>}<text x="445" y="198" textAnchor="middle">{i===3?'I²C page payload in transit':i>=4?'flush complete':'waiting for flush'}</text></svg></div>}</Stepper><p>Moving point is a simplified teaching example. The pinned course provides complete Snake, Breakout and Flap sources and host autopilots; this experiment exposes their shared architecture.</p></>}
 {tab===1&&<><p>Set Y to 40 and press Draw into RAM. RAM point changes while OLED point stays put. Dirty pages are changed eight-row strips awaiting transfer. Press Flush to OLED to make the points match and clear those pages. Force all eight pages and compare the transfer time with the 20 ms update budget; I²C clock sets wire speed.</p><div className="controls"><label>X <input aria-label="Pixel X" type="number" min="0" max="127" value={x} onChange={e=>setX(Math.min(127,Math.max(0,Math.trunc(+e.target.value))))}/></label><label>Y <input aria-label="Pixel Y" type="number" min="0" max="63" value={y} onChange={e=>setY(Math.min(63,Math.max(0,Math.trunc(+e.target.value))))}/></label><button onClick={move}>Draw into RAM</button><button onClick={()=>{setScreen(pixel);setDirty([]);setMessage(`Flush complete: OLED at (${pixel.x},${pixel.y}); dirty mask cleared after successful transfer.`);}}>Flush to OLED</button></div><p role="status">{message}</p><div className="metric-grid"><Metric name="Pixel mapping" value={`page ${addr.page} / column ${x} / bit ${addr.bit}`}/><Metric name="Byte mask" value={`${hex(addr.mask)} · ${addr.mask.toString(2).padStart(8,'0')}`}/><Metric name="RAM point" value={`${pixel.x}, ${pixel.y}`}/><Metric name="OLED point" value={`${screen.x}, ${screen.y}`}/></div><svg className="diagram" viewBox="0 0 600 190" role="img" aria-label={`RAM pixel ${pixel.x},${pixel.y}; OLED pixel ${screen.x},${screen.y}; dirty pages ${dirty.join(', ')||'none'}`}>{[pixel,screen].map((pt,n)=><g key={n}><text x={148+n*300} y="20" textAnchor="middle">{n===0?'SRAM · draw changes here':'OLED · flush changes here'}</text><rect x={20+n*300} y="35" width="256" height="128" fill="none" stroke="currentColor"/>{Array.from({length:8},(_,page)=><rect key={page} x={20+n*300} y={35+page*16} width="256" height="16" fill={n===0&&dirty.includes(page)?'var(--accent-soft)':'none'} stroke="currentColor" strokeOpacity="0.12"/>)}<circle cx={20+n*300+pt.x*2} cy={35+pt.y*2} r="4" fill="currentColor"/></g>)}</svg><div className="controls"><label><input type="checkbox" checked={full} onChange={e=>setFull(e.target.checked)}/> Force all eight pages</label><label>I²C clock <select value={clock} onChange={e=>setClock(+e.target.value)}><option value="100000">100 kHz</option><option value="400000">400 kHz course configuration</option></select></label></div><div className="metric-grid"><Metric name="Pages awaiting flush" value={full?8:dirty.length}/><Metric name="Wire bytes incl. addresses" value={budget.bytes}/><Metric name="Ideal transfer lower bound" value={`${budget.ms.toFixed(3)} ms`}/><Metric name="20 ms update budget" value={budget.ms>20?'EXCEEDED':'fits before software overhead'}/></div><p>138 wire bytes/page × 9 clocks/byte. START/STOP/software overhead excluded. Empty dirty set needs no transport. Clear+redraw can re-dirty pages even when final image is identical.</p><SourceCode label="Actual course excerpts · _lib/oled.c" code={'if (*b != old) { dirty |= (uint8_t)(1u << (y >> 3)); }\nif (!(dirty & (1u << p))) { continue; }'}/></>}
 {tab===2&&<><p>A state machine records the current mode and its allowed transitions. Press START edge to enter play, Pause / resume to suspend or restore logic, then Collision / game over to finish. An edge is a new press, rather than every tick while held. Disabled controls show which actions are invalid in the current mode.</p><svg className="diagram" viewBox="0 0 600 150" role="img" aria-label={`Arcade state ${mode}; allowed transitions menu to play, play to pause or over, pause to play, over to menu`}>{['menu','play','pause','over'].map((state,i)=><g key={state}><rect x={15+i*150} y="45" width="125" height="45" rx="6" fill={state===mode?'var(--accent-soft)':'none'} stroke="currentColor" strokeWidth={state===mode?3:1}/><text x={77+i*150} y="73" textAnchor="middle">{state.toUpperCase()}</text></g>)}<text x="300" y="25" textAnchor="middle">MENU → PLAY ⇄ PAUSE · PLAY → OVER → MENU</text><text x="300" y="125" textAnchor="middle">Current mode selects which inputs may change game logic.</text></svg><div className="metric-grid"><Metric name="Arcade state" value={mode.toUpperCase()}/><Metric name="Model contract" value="start → step → draw → score"/></div><div className="controls"><button disabled={mode!=='menu'} onClick={()=>setMode('play')}>Press START edge</button><button disabled={mode!=='play'&&mode!=='pause'} onClick={()=>setMode(mode==='play'?'pause':'play')}>Pause / resume</button><button disabled={mode!=='play'} onClick={()=>setMode('over')}>Collision / game over</button><button disabled={mode!=='over'} onClick={()=>setMode('menu')}>Return after score lockout</button></div><p>{mode==='menu'?'Choose game and level. Only a new button press begins play.':mode==='play'?'Fixed-step game logic uses pad input; draw edits RAM; flush transports dirty pages.':mode==='pause'?'Game logic is paused; display/menu feedback may still update.':'Course OVER ignores buttons for 0.75 s to avoid an accidental skip. This teaching control explicitly represents returning after that lockout.'}</p><p>State controls are a teaching model of the arcade’s boundaries, not a literal port of arcade.c. Actual score frame: <code>{makeFrame('SCORE,SNAKE,172')}</code>. Python leaderboard validates checksum before recording best score.</p></>}
 </section>;
}
export default function Systems({lessonId}:{lessonId:number}){switch(lessonId){case 7:return <RTOS/>;case 8:return <UART/>;case 9:return <Sensors/>;case 10:return <FixedDMA/>;case 11:return <Faults/>;case 12:return <Game/>;default:return null;}}
